-- Supabase PostgreSQL schema for the Flask store application.
-- Run once in Supabase SQL Editor before setting DATABASE_URL in Vercel.
-- This creates an empty schema; migrate existing MySQL data separately.

CREATE TABLE "Roles" (
  "RoleID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoleName" VARCHAR(50) NOT NULL UNIQUE,
  "Description" VARCHAR(255)
);

CREATE TABLE "Permissions" (
  "PermissionID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PermissionCode" VARCHAR(100) NOT NULL UNIQUE,
  "PermissionName" VARCHAR(150) NOT NULL,
  "Module" VARCHAR(50) NOT NULL
);

CREATE TABLE "Role_Permissions" (
  "RoleID" INT NOT NULL,
  "PermissionID" INT NOT NULL,
  PRIMARY KEY ("RoleID", "PermissionID"),
  CONSTRAINT fk_rp_role FOREIGN KEY ("RoleID") REFERENCES "Roles"("RoleID") ON DELETE CASCADE,
  CONSTRAINT fk_rp_permission FOREIGN KEY ("PermissionID") REFERENCES "Permissions"("PermissionID") ON DELETE CASCADE
);

CREATE TABLE "Users" (
  "UserID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoleID" INT,
  "Username" VARCHAR(50) NOT NULL UNIQUE,
  "PasswordHash" VARCHAR(255) NOT NULL,
  "FullName" VARCHAR(100) NOT NULL,
  "Email" VARCHAR(100) UNIQUE,
  "Phone" VARCHAR(20),
  "IsDeleted" SMALLINT DEFAULT 0,
  "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "DeletedAt" TIMESTAMP,
  CONSTRAINT fk_users_role FOREIGN KEY ("RoleID") REFERENCES "Roles"("RoleID") ON DELETE SET NULL
);

CREATE TABLE "User_Logs" (
  "LogID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserID" INT,
  "Action" VARCHAR(100) NOT NULL,
  "Module" VARCHAR(50) NOT NULL,
  "IPAddress" VARCHAR(45),
  "UserAgent" VARCHAR(255),
  "Description" TEXT,
  "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_logs_user FOREIGN KEY ("UserID") REFERENCES "Users"("UserID") ON DELETE SET NULL
);

CREATE TABLE "Customer_Groups" (
  "GroupID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "GroupName" VARCHAR(50) NOT NULL,
  "DiscountPercent" DECIMAL(5,2) DEFAULT 0.00,
  "MinSpent" DECIMAL(15,2) DEFAULT 0.00
);

CREATE TABLE "Customers" (
  "CustomerID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "GroupID" INT,
  "FullName" VARCHAR(100) NOT NULL,
  "Username" VARCHAR(50) UNIQUE,
  "Phone" VARCHAR(20) NOT NULL UNIQUE,
  "Email" VARCHAR(100) UNIQUE,
  "PasswordHash" VARCHAR(255),
  "TotalSpent" DECIMAL(15,2) DEFAULT 0.00,
  "RewardPoints" INT DEFAULT 0,
  "IsDeleted" SMALLINT DEFAULT 0,
  "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "DeletedAt" TIMESTAMP,
  CONSTRAINT fk_customers_group FOREIGN KEY ("GroupID") REFERENCES "Customer_Groups"("GroupID") ON DELETE SET NULL
);

CREATE TABLE "Password_Reset_Tokens" (
  "PasswordResetID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserID" INT,
  "CustomerID" INT,
  "TokenHash" CHAR(64) NOT NULL UNIQUE,
  "ExpiresAt" TIMESTAMP NOT NULL,
  "UsedAt" TIMESTAMP,
  "FailedAttempts" SMALLINT NOT NULL DEFAULT 0,
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_password_reset_account CHECK (
    ("UserID" IS NOT NULL AND "CustomerID" IS NULL)
    OR ("UserID" IS NULL AND "CustomerID" IS NOT NULL)
  ),
  CONSTRAINT fk_password_reset_user FOREIGN KEY ("UserID") REFERENCES "Users"("UserID") ON DELETE CASCADE,
  CONSTRAINT fk_password_reset_customer FOREIGN KEY ("CustomerID") REFERENCES "Customers"("CustomerID") ON DELETE CASCADE
);

CREATE TABLE "Customer_Login_Logs" (
  "LoginLogID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CustomerID" INT NOT NULL,
  "LoggedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "IPAddress" VARCHAR(45),
  "UserAgent" VARCHAR(255),
  CONSTRAINT fk_customer_login_logs_customer
    FOREIGN KEY ("CustomerID") REFERENCES "Customers"("CustomerID") ON DELETE CASCADE
);

CREATE TABLE "Customer_Addresses" (
  "AddressID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CustomerID" INT NOT NULL,
  "ReceiverName" VARCHAR(100) NOT NULL,
  "ReceiverPhone" VARCHAR(20) NOT NULL,
  "AddressDetail" VARCHAR(255) NOT NULL,
  "ProvinceCity" VARCHAR(100) NOT NULL,
  "IsDefault" SMALLINT DEFAULT 0,
  CONSTRAINT fk_addresses_customer FOREIGN KEY ("CustomerID") REFERENCES "Customers"("CustomerID") ON DELETE CASCADE
);

CREATE TABLE "Promotions" (
  "PromotionID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Code" VARCHAR(50) NOT NULL UNIQUE,
  "Title" VARCHAR(150) NOT NULL,
  "DiscountType" VARCHAR(20) NOT NULL,
  "DiscountValue" DECIMAL(15,2) NOT NULL,
  "MinOrderAmount" DECIMAL(15,2) DEFAULT 0.00,
  "MaxDiscountAmount" DECIMAL(15,2),
  "UsageLimit" INT DEFAULT 0,
  "UsedCount" INT DEFAULT 0,
  "StartDate" TIMESTAMP NOT NULL,
  "EndDate" TIMESTAMP NOT NULL,
  "IsActive" SMALLINT DEFAULT 1
);

CREATE TABLE "Categories" (
  "CategoryID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CategoryName" VARCHAR(100) NOT NULL,
  "ParentID" INT,
  "Description" TEXT,
  CONSTRAINT fk_categories_parent FOREIGN KEY ("ParentID") REFERENCES "Categories"("CategoryID") ON DELETE SET NULL
);

CREATE TABLE "Suppliers" (
  "SupplierID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SupplierName" VARCHAR(150) NOT NULL,
  "Phone" VARCHAR(20),
  "Email" VARCHAR(100),
  "Address" VARCHAR(255),
  "TaxCode" VARCHAR(50)
);

CREATE TABLE "Products" (
  "ProductID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CategoryID" INT,
  "SupplierID" INT,
  "SKU" VARCHAR(50) NOT NULL UNIQUE,
  "Barcode" VARCHAR(50) UNIQUE,
  "ProductName" VARCHAR(200) NOT NULL,
  "MainImage" VARCHAR(500),
  "Specifications" TEXT,
  "CostPrice" DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  "SellingPrice" DECIMAL(15,2) NOT NULL,
  "StockQuantity" INT DEFAULT 0,
  "WarrantyMonths" INT DEFAULT 12,
  "IsHasSerial" SMALLINT DEFAULT 1,
  "IsDeleted" SMALLINT DEFAULT 0,
  "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "UpdatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "DeletedAt" TIMESTAMP,
  CONSTRAINT fk_products_category FOREIGN KEY ("CategoryID") REFERENCES "Categories"("CategoryID") ON DELETE SET NULL,
  CONSTRAINT fk_products_supplier FOREIGN KEY ("SupplierID") REFERENCES "Suppliers"("SupplierID") ON DELETE SET NULL
);

CREATE TABLE "Product_Images" (
  "ImageID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ProductID" INT NOT NULL,
  "ImageUrl" VARCHAR(500) NOT NULL,
  "IsMain" SMALLINT DEFAULT 0,
  "SortOrder" INT DEFAULT 0,
  "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_images_product FOREIGN KEY ("ProductID") REFERENCES "Products"("ProductID") ON DELETE CASCADE
);

CREATE TABLE "Product_Serials" (
  "SerialID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ProductID" INT NOT NULL,
  "SerialNumber" VARCHAR(100) NOT NULL UNIQUE,
  "Status" VARCHAR(20) DEFAULT 'AVAILABLE',
  "InboundDetailID" INT,
  "OrderDetailID" INT,
  CONSTRAINT fk_serials_product FOREIGN KEY ("ProductID") REFERENCES "Products"("ProductID") ON DELETE CASCADE
);

CREATE TABLE "Inbound_Notes" (
  "InboundID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SupplierID" INT,
  "CreatedBy" INT,
  "ImportDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "TotalAmount" DECIMAL(15,2) NOT NULL,
  "Status" VARCHAR(20) DEFAULT 'COMPLETED',
  "Notes" TEXT,
  CONSTRAINT fk_inbound_supplier FOREIGN KEY ("SupplierID") REFERENCES "Suppliers"("SupplierID") ON DELETE SET NULL,
  CONSTRAINT fk_inbound_user FOREIGN KEY ("CreatedBy") REFERENCES "Users"("UserID") ON DELETE SET NULL
);

CREATE TABLE "Inbound_Details" (
  "InboundDetailID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "InboundID" INT NOT NULL,
  "ProductID" INT NOT NULL,
  "Quantity" INT NOT NULL,
  "ImportPrice" DECIMAL(15,2) NOT NULL,
  CONSTRAINT fk_indetail_note FOREIGN KEY ("InboundID") REFERENCES "Inbound_Notes"("InboundID") ON DELETE CASCADE,
  CONSTRAINT fk_indetail_product FOREIGN KEY ("ProductID") REFERENCES "Products"("ProductID") ON DELETE CASCADE
);

CREATE TABLE "Orders" (
  "OrderID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "OrderCode" VARCHAR(50) NOT NULL UNIQUE,
  "CustomerID" INT,
  "EmployeeID" INT,
  "PromotionID" INT,
  "SubTotal" DECIMAL(15,2) NOT NULL,
  "DiscountAmount" DECIMAL(15,2) DEFAULT 0.00,
  "TotalAmount" DECIMAL(15,2) NOT NULL,
  "OrderStatus" VARCHAR(20) DEFAULT 'PENDING',
  "OrderDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "Notes" TEXT,
  CONSTRAINT fk_orders_customer FOREIGN KEY ("CustomerID") REFERENCES "Customers"("CustomerID") ON DELETE SET NULL,
  CONSTRAINT fk_orders_employee FOREIGN KEY ("EmployeeID") REFERENCES "Users"("UserID") ON DELETE SET NULL,
  CONSTRAINT fk_orders_promotion FOREIGN KEY ("PromotionID") REFERENCES "Promotions"("PromotionID") ON DELETE SET NULL
);

CREATE TABLE "Order_Details" (
  "OrderDetailID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "OrderID" INT NOT NULL,
  "ProductID" INT NOT NULL,
  "Quantity" INT NOT NULL,
  "UnitPrice" DECIMAL(15,2) NOT NULL,
  "TotalPrice" DECIMAL(15,2) NOT NULL,
  CONSTRAINT fk_odetail_order FOREIGN KEY ("OrderID") REFERENCES "Orders"("OrderID") ON DELETE CASCADE,
  CONSTRAINT fk_odetail_product FOREIGN KEY ("ProductID") REFERENCES "Products"("ProductID") ON DELETE CASCADE
);

CREATE TABLE "Payments" (
  "PaymentID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "OrderID" INT NOT NULL,
  "Amount" DECIMAL(15,2) NOT NULL,
  "PaidAmount" DECIMAL(15,2) DEFAULT 0.00,
  "PaymentMethod" VARCHAR(20) NOT NULL,
  "PaymentStatus" VARCHAR(20) DEFAULT 'UNPAID',
  "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_payments_order FOREIGN KEY ("OrderID") REFERENCES "Orders"("OrderID") ON DELETE CASCADE
);

CREATE TABLE "Payment_Transactions" (
  "TransactionID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PaymentID" INT NOT NULL,
  "TransCode" VARCHAR(100),
  "Amount" DECIMAL(15,2) NOT NULL,
  "PayGateway" VARCHAR(50),
  "GatewayResponse" TEXT,
  "Status" VARCHAR(20) DEFAULT 'PENDING',
  "TransactionTime" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_ptrans_payment FOREIGN KEY ("PaymentID") REFERENCES "Payments"("PaymentID") ON DELETE CASCADE
);

CREATE TABLE "Warranties" (
  "WarrantyID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "OrderDetailID" INT NOT NULL,
  "SerialNumber" VARCHAR(100) NOT NULL,
  "StartDate" DATE NOT NULL,
  "EndDate" DATE NOT NULL,
  "Status" VARCHAR(20) DEFAULT 'ACTIVE',
  CONSTRAINT fk_warranties_odetail FOREIGN KEY ("OrderDetailID") REFERENCES "Order_Details"("OrderDetailID") ON DELETE CASCADE
);

CREATE INDEX idx_password_reset_expiry ON "Password_Reset_Tokens" ("ExpiresAt", "UsedAt");

ALTER TABLE "Product_Serials" ADD CONSTRAINT fk_serials_inbound FOREIGN KEY ("InboundDetailID") REFERENCES "Inbound_Details"("InboundDetailID") ON DELETE SET NULL;

ALTER TABLE "Product_Serials" ADD CONSTRAINT fk_serials_orderdetail FOREIGN KEY ("OrderDetailID") REFERENCES "Order_Details"("OrderDetailID") ON DELETE SET NULL;

CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW."UpdatedAt" = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "trg_users_updated_at" BEFORE UPDATE ON "Users" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER "trg_customers_updated_at" BEFORE UPDATE ON "Customers" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER "trg_products_updated_at" BEFORE UPDATE ON "Products" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE "Roles" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Permissions" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Role_Permissions" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Users" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "User_Logs" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Customer_Groups" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Customers" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Password_Reset_Tokens" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Customer_Login_Logs" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Customer_Addresses" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Promotions" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Categories" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Suppliers" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Products" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Product_Images" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Product_Serials" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Inbound_Notes" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Inbound_Details" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Orders" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Order_Details" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Payments" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Payment_Transactions" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "Warranties" ENABLE ROW LEVEL SECURITY;
